Database.DMLOptions opts = new Database.DMLOptions();
opts.DuplicateRuleHeader.AllowSave = true;
opts.DuplicateRuleHeader.RunAsCurrentUser = true;
System.assertEquals(true, opts.DuplicateRuleHeader.AllowSave);
System.assertEquals(true, opts.DuplicateRuleHeader.RunAsCurrentUser);
Database.SaveResult result = Database.insert(new Account(Name = 'Accepted'), opts);
System.assert(result.isSuccess());
System.assertEquals(1, [SELECT COUNT() FROM Account WHERE Name = 'Accepted']);

